import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { toast } from '../libs/toast';
import { FaPlus, FaEdit, FaTrash, FaSearch, FaUser } from 'react-icons/fa';
import axios from 'axios';
import './Actors.css';
import { toPersianDigits } from '../utils/locale';

const Actors: React.FC = () => {
  const [actors, setActors] = useState([]);
  const [filteredActors, setFilteredActors] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchActors();
  }, []);

  useEffect(() => {
    filterActors();
  }, [actors, searchTerm]);

  const fetchActors = async () => {
    try {
      const response = await axios.get('/api/actors');
      setActors(response.data);
    } catch (error) {
      toast.error('خطا در دریافت لیست عوامل');
    } finally {
      setLoading(false);
    }
  };

  const filterActors = () => {
    let filtered = actors;

    if (searchTerm) {
      filtered = filtered.filter((actor: any) =>
        actor.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        actor.role?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        actor.phone?.includes(searchTerm) ||
        actor.email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredActors(filtered);
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('آیا از حذف این عامل مطمئن هستید؟')) {
      try {
        await axios.delete(`/api/actors/${id}`);
        toast.success('عامل با موفقیت حذف شد');
        fetchActors();
      } catch (error) {
        toast.error('خطا در حذف عامل');
      }
    }
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>در حال بارگذاری...</p>
      </div>
    );
  }

  return (
    <div className="actors-container">
      <div className="page-header">
        <h1>مدیریت عوامل</h1>
        <Link to="/actors/new" className="btn btn-success">
          <FaPlus />
          عامل جدید
        </Link>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <FaSearch />
          <input
            type="text"
            placeholder="جستجو در نام، نقش، تلفن یا ایمیل..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
      </div>

      <div className="actors-grid">
        {filteredActors.length === 0 ? (
          <div className="empty-state">
            <FaUser />
            <p>هیچ عاملی یافت نشد</p>
            <Link to="/actors/new" className="btn btn-success">
              ایجاد اولین عامل
            </Link>
          </div>
        ) : (
          filteredActors.map((actor: any) => (
            <div key={actor.id} className="actor-card">
              <div className="card-header">
                <div className="actor-info">
                  <div className="actor-avatar">
                    <FaUser />
                  </div>
                  <div className="actor-details">
                    <h3>{actor.name}</h3>
                    {actor.role && <p className="actor-role">{actor.role}</p>}
                  </div>
                </div>
                <div className="card-actions">
                  <Link
                    to={`/actors/${actor.id}/edit`}
                    className="action-btn edit"
                    title="ویرایش"
                  >
                    <FaEdit />
                  </Link>
                  <button
                    onClick={() => handleDelete(actor.id)}
                    className="action-btn delete"
                    title="حذف"
                  >
                    <FaTrash />
                  </button>
                </div>
              </div>

              <div className="card-content">
                {actor.phone && (
                  <div className="info-item">
                    <span className="label">تلفن:</span>
                    <span className="value">{toPersianDigits(actor.phone)}</span>
                  </div>
                )}
                {actor.email && (
                  <div className="info-item">
                    <span className="label">ایمیل:</span>
                    <span className="value">{actor.email}</span>
                  </div>
                )}
                {actor.address && (
                  <div className="info-item">
                    <span className="label">آدرس:</span>
                    <span className="value">{actor.address}</span>
                  </div>
                )}
                {actor.description && (
                  <div className="info-item">
                    <span className="label">توضیحات:</span>
                    <span className="value">{actor.description}</span>
                  </div>
                )}
              </div>

              <div className="card-footer">
                <div className="created-info">
                  ایجاد شده در: {new Date(actor.created_at).toLocaleDateString('fa-IR')}
                </div>
                <div className="status-badge">
                  {actor.status === 'active' ? 'فعال' : 'غیرفعال'}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Actors;
